function broken(m) { console.error("ERROR: " + m); process.exit(2); }
const dir = fs.mkdtempSync(path.join(require("os").tmpdir(), "wb-"));
fs.writeFileSync(path.join(dir, "secrets.json"), JSON.stringify({ OLD_KEY: null, NEW_KEY: "new" }));
let patch = null;
const server = http.createServer((req, res) => {
  let b = "";
  req.on("data", (c) => (b += c));
  req.on("end", () => {
    if (req.method === "PATCH" && /versions\/latest/.test(req.url)) patch = JSON.parse(b);
    res.setHeader("Content-Type", "application/json");
    res.end(JSON.stringify({ success: true, errors: [], messages: [], result: { id: "ver-1" } }));
  });
});
server.listen(0, "127.0.0.1", () => {
