    env: { ...process.env, HOME: dir, CLOUDFLARE_API_TOKEN: "tok", CLOUDFLARE_ACCOUNT_ID: "acc", CLOUDFLARE_API_BASE_URL: "http://127.0.0.1:" + port + "/client/v4", WRANGLER_SEND_METRICS: "false", CI: "true", NO_COLOR: "1", WRANGLER_LOG_PATH: path.join(dir, "logs") },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let out = "";
